import math

def solve_problem():
    solutions = []

    for n in range(2, 200):
        if math.gcd(n, 6) != 1:
            continue

        is_valid_n = True

        # Find valid 'a' values: n/3 < a <= n/2
        # Start a from floor(n/3) + 1 up to floor(n/2)
        a_start = math.floor(n / 3) + 1
        a_end = math.floor(n / 2)

        if a_start > a_end:
            # Should not happen for n >= 2, but good practice
            continue

        for a in range(a_start, a_end + 1):
            # Calculate the modulus r = n - 2a. Since a <= n/2, r >= 0.
            r = n - 2 * a

            # r must be positive for the division/modulus to be meaningful in this context
            # We established r >= 1 because n is odd and 2a is even.
            if r <= 0:
                continue

            # The condition is: binomial coefficient C(a-1, r-1) is divisible by r
            # Note: If r=1, r-1=0, C(a-1, 0) = 1. 1 % 1 = 0. Always true.
            if r == 1:
                if not (1 % 1 == 0):
                    # This branch should never be hit, but for safety
                    is_valid_n = False
                    break
                continue

            # Need C(a-1, r-1) % r == 0
            try:
                C = math.comb(a - 1, r - 1)
            except ValueError:
                # This happens if r-1 < 0 or r-1 > a-1.
                # Since r = n-2a and r <= a (because a > n/3), we have r-1 < a-1 is highly likely.
                # If r-1 > a-1, then C is 0, which is divisible by r (assuming r > 0).
                if r - 1 > a - 1:
                     if r > 0 and 0 % r == 0:
                         continue
                     else:
                         is_valid_n = False
                         break
                else:
                    # General case
                    if C % r != 0:
                        is_valid_n = False
                        # print(f"FAIL: n={n}, a={a}, r={r}. C(a-1, r-1)={C}, C mod r = {C % r}")
                        break

        if is_valid_n:
            solutions.append(n)

    return sorted(solutions)

results = solve_problem()
print("Calculated Solutions:")
print(results)
print("Count:", len(results))
